{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "In seven patients, tetrabenazine had a mean oral systemic availability of 0.049 ± 0.032 after oral dosing, directly measured against IV, providing strong human evidence of very low oral bioavailability for a related small-molecule CNS drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Terameprocol showed absolute oral bioavailability of approximately 2% in a phase 1 trial in patients with recurrent high-grade gliomas, supporting low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "ThH tablets were reported to have very low oral bioavailability in humans, supporting a low-F prediction for a related small molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "M6G had poor oral bioavailability in humans, requiring intravenous administration, consistent with low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Compound 26 was predicted to have 0% oral bioavailability in humans, supporting low oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple independent human studies of related small molecules consistently report very low oral bioavailability (0–8.5%), all below the 20% threshold. This experimental evidence outweighs the favorable physicochemical prior, so the query is predicted to have low oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement is available for the query molecule itself.",
    "The structural and mechanistic relationship between the query and the low-bioavailability reference molecules is not explicitly defined in the provided context.",
    "The favorable physicochemical prior is indirect and cannot resolve the conflict with direct human low-F data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

